package com.digitalbase.ticketing.dto;import com.fasterxml.jackson.annotation.JsonPropertyOrder; // 👈 Import ထည့်ပါimport lombok.Builder;import lombok.Data;import java.util.List;@Data@Builder// 🎯 [အပြောင်းအလဲ] JSON တွင် ဖော်ပြမည့် အစီအစဉ်ကို အတိအကျ သတ်မှတ်ခြင်း@JsonPropertyOrder({        "requestId",        "status",        "submittedDateText",        "submittedBy",        "companyName",        "phoneNumber",        "contactEmail",        "relatedProduct",        "productType",        "requestChangePlanName",        "preferredStartDate",        "serviceHoursText",        "monthlyFeesText",        "upgradeReason",        "currentPlanDetails",        "requestPlanDetails"})public class PlanUpgradeRequestDetailResponse {    private String requestId;    private String status;    private String submittedDateText;    private String submittedBy;    private String companyName;    private String phoneNumber;    private String contactEmail;    private String relatedProduct;    private String productType;    private String requestChangePlanName;    private String preferredStartDate;    private String serviceHoursText;    private String monthlyFeesText;    private String upgradeReason;    private PlanDetail currentPlanDetails;    private PlanDetail requestPlanDetails;    @Data    @Builder    // 🎯 [အပြောင်းအလဲ] အတွင်းဘက် Object အတွက်လည်း အစီအစဉ်ကို အတိအကျ သတ်မှတ်ခြင်း    @JsonPropertyOrder({            "planName",            "status",            "monthlyFeesText",            "description",            "supportHoursText",            "responseTime",            "serviceSchedule",            "paymentTerms",            "discountOnRetainer",            "hourlyRateText",            "servicesIncluded"    })    public static class PlanDetail {        private String planName;        private String status;        private String monthlyFeesText;        private String description;        private String supportHoursText;        private String responseTime;        private String serviceSchedule;        // အကယ်၍ အစ်ကို့အနေဖြင့် ဤ Field များကို null ဖြစ်နေပါက အောက်ဆုံးတွင် ထားလိုသဖြင့် အောက်သို့ ပို့ထားပါသည်        private String paymentTerms;        private String discountOnRetainer;        private String hourlyRateText;        private List<String> servicesIncluded;    }}